{
  "characters": [
    {
      "name": "Sherlock Holmes",
      "aliases": ["Holmes"],
      "description": "Consulting detective, roommate of Dr. Watson at Baker Street, early riser, keen observer.",
      "facts": [
        "Lives with Dr. Watson as bachelors in Baker Street.",
        "Was awakened at quarter-past seven by Dr. Watson.",
        "Has a casebook and consults it for client details."
      ]
    },
    {
      "name": "Dr. John H. Watson",
      "aliases": ["Watson"],
      "description": "Friend and associate of Sherlock Holmes, narrator, shares rooms with Holmes on Baker Street.",
      "facts": [
        "Wakes at quarter-past seven to find Holmes at his bedside.",
        "Has been studying Holmes' methods for eight years across seventy cases.",
        "Accompanies Holmes to the sitting‑room to meet the client."
      ]
    },
    {
      "name": "Mrs. Hudson",
      "aliases": ["Mrs. Hudson"],
      "description": "Landlady of Holmes and Watson's rooms on Baker Street.",
      "facts": [
        "Has lit the fire in the sitting‑room when the client arrives."
      ]
    },
    {
      "name": "Mrs. Farintosh",
      "aliases": ["Mrs. Farintosh"],
      "description": "Previous client of Holmes, mentioned by the lady as a reference.",
      "facts": [
        "Holmes helped her with an opal tiara case."
      ]
    },
    {
      "name": "Unnamed Lady",
      "aliases": ["the lady", "madam"],
      "description": "A woman in her thirties, veiled, pale and agitated, seeking Holmes' help.",
      "facts": [
        "Arrived by train from Leatherhead early that morning.",
        "Travelled in a dog‑cart, left arm of jacket spattered with mud in seven fresh places.",
        "Holds the second half of a return ticket in her left glove.",
        "Will be married in a month or six weeks and will have her own income.",
        "Fears an unspecified danger and feels ignored by a male confidant."
      ]
    }
  ],
  "places": [
    {
      "name": "Baker Street",
      "description": "London address where Holmes and Watson share rooms as bachelors."
    },
    {
      "name": "Sitting‑room (Holmes' flat)",
      "description": "Room in the Baker Street flat where the lady is waiting."
    },
    {
      "name": "Waterloo Station",
      "description": "London railway terminus where the lady arrived by train."
    },
    {
      "name": "Leatherhead",
      "description": "Town where the lady started her journey before reaching Waterloo."
    }
  ],
  "facts": [
    "The events are set in early April 1883.",
    "Holmes and Watson have been sharing rooms for eight years.",
    "The lady's left‑arm jacket bears seven fresh mud spots."
  ],
  "pronunciations": [
    {
      "term": "Roylott",
      "say_as": "ROY-lot"
    }
  ],
  "clues": [
    {
      "id": "mud_spots_jacket",
      "kind": "presence",
      "quote": "The left arm of your jacket is spattered with mud in no less than seven places. The marks are perfectly fresh.",
      "text": "Seven fresh mud spots on the left arm of the lady's jacket indicate recent travel in a dog‑cart on the left side.",
      "keywords": ["mud", "seven", "fresh"]
    },
    {
      "id": "ticket_half_glove",
      "kind": "presence",
      "quote": "You must have started early, and yet you had a good drive in a dog‑cart, along heavy roads, before you reached the station.",
      "text": "Holmes notes the second half of a return ticket in the lady's left glove, confirming her recent travel.",
      "keywords": ["ticket", "glove", "return"]
    },
    {
      "id": "arrival_time",
      "kind": "presence",
      "quote": "I started from home before six, reached Leatherhead at twenty past, and came in by the first train to Waterloo.",
      "text": "The lady's stated itinerary places her arrival at Waterloo early in the morning, matching the mud evidence.",
      "keywords": ["six", "twenty past", "first train"]
    }
  ],
  "opened_threads": [],
  "closed_threads": []
}

{
  "characters": [
    {
      "name": "Helen Stoner",
      "aliases": ["Helen Stoner", "the lady", "madam"],
      "description": "Young woman living with her stepfather Dr. Roylott at the ancestral house of Stoke Moran; sister of the deceased Julia Stoner.",
      "facts": [
        "She and her sister Julia are twins, two years old when their mother remarried Dr. Roylott.",
        "She is currently residing in the third bedroom of the inhabited wing of Stoke Moran.",
        "She reports hearing a low, clear whistle around three in the morning on several nights."
      ]
    },
    {
      "name": "Dr. Roylott",
      "aliases": ["Dr. Roylott"],
      "description": "Stepfather of Helen and Julia Stoner; former medical practitioner in Calcutta; now lives at Stoke Moran and is noted for violent temper and ownership of exotic Indian animals.",
      "facts": [
        "He obtained a medical degree in Calcutta and established a large practice there.",
        "He beat his native butler to death and served a long prison term before returning to England.",
        "He married Helen's mother, Mrs. Stoner, and inherited her £1000‑a‑year income.",
        "He keeps a cheetah and a baboon that wander freely over his grounds.",
        "He is known to smoke strong Indian cigars."
      ]
    },
    {
      "name": "Miss Honoria Westphail",
      "aliases": ["Miss Honoria Westphail"],
      "description": "Aunt of Helen and Julia Stoner; lives near Harrow; occasional host for short visits.",
      "facts": [
        "She is the maiden sister of Helen's mother."
      ]
    }
  ],
  "places": [
    {
      "name": "Stoke Moran",
      "description": "Old two‑hundred‑year‑old ancestral house on the western border of Surrey, now reduced to a few acres and a heavy mortgage."
    }
  ],
  "facts": [
    "The Roylott family once owned extensive estates extending into Berkshire and Hampshire.",
    "Four successive heirs squandered the family fortune, leaving only the house and a few acres.",
    "Dr. Roylott's stepfather (the last squire) obtained an advance to study medicine in Calcutta."
  ],
  "pronunciations": [],
  "clues": [
    {
      "id": "night_whistle",
      "kind": "presence",
      "text": "Helen reports hearing a low, clear whistle around three in the morning on several nights.",
      "quote": "‘Because during the last few nights I have always, about three in the morning, heard a low, clear whistle.’",
      "keywords": ["low", "clear", "whistle"]
    },
    {
      "id": "cigar_smell",
      "kind": "presence",
      "text": "Julia was troubled by the strong smell of Indian cigars coming from Dr. Roylott’s room.",
      "quote": "she was troubled by the smell of the strong Indian cigars which it was his custom to smoke.",
      "keywords": ["strong", "Indian", "cigars"]
    },
    {
      "id": "blacksmith_hurl",
      "kind": "presence",
      "text": "Dr. Roylott hurled the local blacksmith over a parapet into a stream.",
      "quote": "Last week he hurled the local blacksmith over a parapet into a stream.",
      "keywords": ["hurled", "blacksmith", "parapet"]
    },
    {
      "id": "exotic_animals",
      "kind": "presence",
      "text": "Dr. Roylott keeps a cheetah and a baboon that wander freely over his grounds.",
      "quote": "he has a cheetah and a baboon, which wander freely over his grounds.",
      "keywords": ["cheetah", "baboon", "wander"]
    }
  ],
