  "closed_threads": []
}

{
  "characters": [
    {
      "name": "Percy Armitage",
      "aliases": ["Percy Armitage", "Armitage"],
      "description": "The lady's fiancé; second son of Mr. Armitage of Crane Water near Reading.",
      "facts": [
        "He has asked the lady's hand in marriage.",
        "He is the second son of Mr. Armitage of Crane Water near Reading."
      ]
    }
  ],
  "places": [
    {
      "name": "Crown Inn",
      "description": "An inn opposite the lady's house where she hired a dog‑cart."
    },
    {
      "name": "west wing",
      "description": "The west wing of the Stoke Moran house where repairs pierced the bedroom wall."
    }
  ],
  "facts": [
    "The lady and her sister always locked their doors at night.",
    "The lady heard a low whistle and a clanging metallic sound on the night of her sister's death.",
    "The sister was wearing a night‑dress.",
    "A charred match stump was found in the sister's right hand and a match‑box in her left.",
    "The sister's door was fastened on the inner side; windows were barred with iron bars and shutters; walls and floor were solid; the chimney was barred by four large staples.",
    "No marks of violence or poison were found on the sister.",
    "The lady believes the \"speckled band\" may refer to the spotted handkerchiefs worn by the gipsies in the plantation.",
    "Two years have passed since the sister's death.",
    "The lady is engaged to Percy Armitage, second son of Mr. Armitage of Crane Water near Reading.",
    "Repairs in the west wing pierced the bedroom wall, forcing the lady to move into her sister's former bedroom and bed.",
    "The lady heard the same low whistle again the night before consulting Holmes.",
    "She travelled by dog‑cart from the Crown Inn to Leatherhead on the morning of the interview."
  ],
  "pronunciations": [
    {
      "term": "Armitage",
      "say_as": "AR-mi-tij"
    }
  ],
  "clues": [
    {
      "id": "whistle_again",
      "text": "The lady heard the low whistle again the night before consulting Holmes.",
      "kind": "presence",
      "quote": "I suddenly heard in the silence of the night the low whistle which had been the herald of her own death.",
      "keywords": ["low", "whistle"]
    },
    {
      "id": "metal_clang",
      "text": "A clanging metallic sound was heard shortly after the whistle on the night of the sister's death.",
      "kind": "presence",
      "quote": "a few moments later a clanging sound, as if a mass of metal had fallen.",
      "keywords": ["clanging", "metal"]
    },
    {
      "id": "match_stump",
      "text": "A charred match stump in the right hand and a match‑box in the left hand of the dead sister.",
      "kind": "presence",
      "quote": "In her right hand was found the charred stump of a match, and in her left a match-box.",
      "keywords": ["charred", "match", "match-box"]
    },
    {
      "id": "handprint_spots",
      "text": "Five livid spots, the marks of four fingers and a thumb, printed on the lady's wrist.",
      "kind": "presence",
      "quote": "Five little livid spots, the marks of four fingers and a thumb, were printed upon the white wrist.",
      "keywords": ["livid", "spots", "wrist"]
    }
  ],
  "opened_threads": [
    {
      "id": "identity_speckled_band",
      "question": "What is the true nature of the \"speckled band\" mentioned by the sister?"
    },
    {
      "id": "source_of_whistle",
      "question": "What is producing the low whistle heard on both nights?"
    }
  ],
  "closed_threads": []
}

